import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForBound,validBound,advanceBound,numericBound,cultureCounts,berryOutput,webCases}from './bound-models.js?v=20261023-physicscomplete01';import{showBound}from './bound-visuals.js?v=20261023-physicscomplete01';export{showBound};
export function mountBound(l,p,root,{save,done,feedback}){let ts=tasksForBound(l.widget.slice(6)),w=p.widget;w.boundTask??=ts[0].id;w.boundDrafts??={};w.boundPassed??=[];let i=ts.findIndex(t=>t.id===w.boundTask);if(i<0)i=0;let t=ts[i],v=w.boundDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountBound(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.boundPassed.includes(t.id));
syncProcessMovie(l,1,!['resistance','community-process'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('boundCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('boundAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealBound">Reveal evidence →</button><p id="boundReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showBound(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#boundReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validBound(c,v.answer);}
else if(t.type==='sequence'){body=field('boundNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceBound">Advance pathway →</button><p id="boundReadout" aria-live="polite"></p>';draw=()=>{showBound(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#boundReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='culture'||t.type==='web'){v.treatment??='no';v.water??='wet';v.pollinators??='yes';v.stage??=0;v.observations??=[];let culture=t.type==='culture';body=culture?field('boundTreatment','Antibiotic',[['no','Absent'],['yes','Present']],v.treatment):field('boundWater','Water',[['wet','Adequate'],['dry','Dry']],v.water)+field('boundPollinators','Pollinators',[['yes','Present'],['no','Absent']],v.pollinators);body+='<label class="field-label" for="boundPrediction">'+(culture?'Predict resistant percentage after exposure and one division':'Predict berry output / toy units')+'</label><input class="lab-input" id="boundPrediction" type="number" value="'+(v.prediction??'')+'"><button class="secondary" id="runBound">'+(culture?'Advance exposure / division →':'Run model →')+'</button><p id="boundReadout" aria-live="polite"></p>';draw=()=>{showBound(t.kind,{treatment:v.treatment,stage:v.stage,water:v.water,pollinators:v.pollinators,revealed:v.stage>0,title:t.title});$('#boundReadout').textContent=culture?'Stage '+v.stage+' / 2 · susceptible '+cultureCounts(v.treatment,v.stage).susceptible+', resistant '+cultureCounts(v.treatment,v.stage).resistant+'; resistant '+cultureCounts(v.treatment,v.stage).percent+'%':(v.stage?'Toy output: '+berryOutput(v.water,v.pollinators):'Predict before running.');};valid=()=>v.stage>=(culture?2:1)&&numericBound(v.prediction,culture?cultureCounts(v.treatment,2).percent:berryOutput(v.water,v.pollinators));}

else{body='<p>'+t.prompt+'</p><label class="field-label" for="boundNumber">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="boundNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('boundReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showBound(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericBound(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="boundEvidence"></p><div class="lab-actions"><button class="secondary" id="recordBound">Record reasoning</button><button class="secondary" id="nextBound">Next challenge →</button></div><p id="boundProgress"></p>';
const status=()=>{$('#boundEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.boundPassed.includes(t.id)?'Challenge recorded.':'';if(t.type==='culture'||t.type==='web')$('#boundEvidence').textContent='Recorded conditions: '+v.observations.map(k=>t.type==='culture'?'antibiotic '+(k==='yes'?'present':'absent'):(k.startsWith('wet')?'adequate water':'dry')+' / pollinators '+(k.endsWith('yes')?'present':'absent')).join('; ');$('#boundProgress').textContent=ts.filter(t=>w.boundPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='boundCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(['boundTreatment','boundWater','boundPollinators'].includes(id)){if(!val){remount();return;}v[id==='boundTreatment'?'treatment':id==='boundWater'?'water':'pollinators']=val;v.stage=0;v.prediction='';save();remount();return;}if(id==='boundPrediction')v.prediction=val;else if(id==='boundAnswer')v.answer=val;else if(id==='boundNext')v.next=val;else if(id==='boundNumber')v.number=val;else if(id==='boundReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{if(e.target.id==='boundPrediction')v.prediction=e.target.value;else v.number=e.target.value;save();};}
if($('#runBound'))$('#runBound').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Make a numerical prediction first.',true);return;}v.stage=t.type==='culture'?Math.min(2,v.stage+1):1;save();draw();feedback('Compare the output with your prediction.');};
if($('#revealBound'))$('#revealBound').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validBound(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validBound(t.cases[v.case],v.answer));};
if($('#advanceBound'))$('#advanceBound').onclick=()=>{let n=advanceBound(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordBound').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='culture'||t.type==='web'){let key=t.type==='culture'?v.treatment:v.water+':'+v.pollinators;if(!v.observations.includes(key))v.observations.push(key);}let finished=t.type==='culture'?['no','yes'].every(k=>v.observations.includes(k)):t.type==='web'?webCases.every(k=>v.observations.includes(k)):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.boundPassed.includes(t.id))w.boundPassed.push(t.id);p.widgetDone=ts.every(t=>w.boundPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextBound').onclick=()=>{if(!w.boundPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.boundTask=ts[(i+1)%ts.length].id;save();remount();};}
